{"file_path":"/work/tests/test_spec.py","content":"import pytest

from sales_dashboard.loader import (
    daily_conversion_counts,
    dedupe_sessions,
    parse_session_log,
)
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def session(id_, day, converted):
    return {"id": id_, "day": day, "converted": converted}


def test_conversion_rate_none_counts_as_not_converted():
    events = [session("a", 1, True), session("b", 1, None)]
    assert conversion_rate(events) == 0.5
    assert conversion_rate([session("b", 1, None)]) == 0.0


def test_conversion_rate_empty():
    result = conversion_rate([])
    assert result == 0.0
    assert isinstance(result, float)


def test_pooled_conversion_rate_weights_sessions_not_groups():
    groups = {
        "small": [session("a", 1, True)],
        "large": [session(str(i), 1, False) for i in range(3)],
        "unknown": [session("b", 1, None)],
        "empty": [],
    }
    assert pooled_conversion_rate(groups) == 0.2


@pytest.mark.parametrize("groups", [{}, {"empty": []}, {"a": [], "b": []}])
def test_pooled_conversion_rate_no_sessions(groups):
    result = pooled_conversion_rate(groups)
    assert result == 0.0
    assert isinstance(result, float)


@pytest.mark.parametrize(
    "counts, days, expected",
    [([], 0, 0), ([], 3, 0), ([1, 2, 4], 0, 0), ([1, 2, 4], 1, 4),
     ([1, 2, 4], 2, 6), ([1, 2, 4], 3, 7), ([1, 2, 4], 10, 7)],
)
def test_conversions_in_window(counts, days, expected):
    assert conversions_in_window(counts, days) == expected


def test_parse_session_log_flags_and_field_whitespace():
    assert parse_session_log([" a , 1 , 1 \n", " b , -2 , 0 ", " c , 3 , \t"]) == [
        session("a", 1, True), session("b", -2, False), session("c", 3, None)
    ]


def test_parse_session_log_skips_blank_and_comment_lines():
    lines = iter(["", "\n", " \t\n", "# comment", " \t# ignored, even, with, commas",
                  "a,2,1", "", "b,3,0"])
    assert parse_session_log(lines) == [session("a", 2, True), session("b", 3, False)]


@pytest.mark.parametrize("bad_line", ["a", "a,1", "a,1,1,extra", "a,no,1", "a,1.5,0", "a,,1"])
def test_parse_session_log_errors_include_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"\bline 5\b"):
        parse_session_log(["", " # comment", "a,1,1", " \t", bad_line])


def test_dedupe_sessions_keeps_last_duplicate_id_and_sorts():
    events = [
        session("b", 9, True), session("a", 2, True), session("c", 1, None),
        session("b", 2, False), session("a", 2, None),
    ]
    original = [event.copy() for event in events]
    assert dedupe_sessions(events) == [events[2], events[4], events[3]]
    assert events == original
    assert dedupe_sessions([]) == []


def test_daily_conversion_counts_inclusive_zero_filled_range():
    events = [
        session("before", 0, True), session("a", 1, True), session("b", 1, True),
        session("c", 2, False), session("d", 2, None), session("e", 4, True),
        session("after", 5, True),
    ]
    assert daily_conversion_counts(events, 1, 4) == [2, 0, 0, 1]
    assert daily_conversion_counts(events, 1, 1) == [2]
    assert daily_conversion_counts(events, 4, 1) == []


def test_daily_conversion_counts_no_sessions():
    assert daily_conversion_counts([], -1, 1) == [0, 0, 0]
    assert daily_conversion_counts([], 1, 0) == []


@pytest.mark.parametrize("days, recent", [(0, 0), (1, 0), (2, 1), (3, 1), (20, 2)])
def test_campaign_summary_uses_calendar_window_and_pooled_rate(days, recent):
    groups = {
        "small": [session("a", 1, True)],
        "large": [session("b", 4, True), session("c", 5, False),
                  session("d", 1, None), session("e", 1, False), session("f", 1, False)],
        "empty": [],
    }
    assert campaign_summary(groups, days) == {"rate": 0.333, "recent": recent, "groups": 2}


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_campaign_summary_no_sessions(groups):
    assert campaign_summary(groups, 5) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_converting_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {
        "z": [session("a", 1, True)],
        "empty": [],
        "low": [session("b", 1, True), session("c", 1, None)],
        "a": [session("d", 1, True)],
        "zero": [session("e", 1, False)],
    }
    assert top_converting_groups(groups, 2) == ["a", "z"]
    assert top_converting_groups(groups, 10) == ["a", "z", "low", "zero"]
    assert top_converting_groups(groups, 0) == []
    assert top_converting_groups({}, 2) == []
    assert top_converting_groups({"empty": []}, 2) == []


def test_conversion_rate_by_group_sorted_with_empty_groups_none():
    groups = {
        "z": [session("a", 1, True), session("b", 1, None)],
        "empty": [],
        "a": [session("c", 1, False)],
    }
    rates = conversion_rate_by_group(groups)
    assert rates == {"a": 0.0, "empty": None, "z": 0.5}
    assert list(rates) == ["a", "empty", "z"]
    assert conversion_rate_by_group({}) == {}


@pytest.mark.parametrize(
    "counts, expected",
    [([], 0), ([0, 0], 0), ([-1, 0, -2], 0), ([1, 2, 3], 3),
     ([1, 0, 2, 3, 0, 4], 2), ([1, 2, -1, 3, 4, 5], 3), ([0, 2, 0], 1)],
)
def test_longest_conversion_streak(counts, expected):
